PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS agentes (id INTEGER PRIMARY KEY, nombre TEXT NOT NULL, area TEXT NOT NULL CHECK(area IN ('hardware','software','redes')), activo INTEGER NOT NULL DEFAULT 1 CHECK(activo IN (0,1)));
CREATE TABLE IF NOT EXISTS clientes (id INTEGER PRIMARY KEY, nombre TEXT NOT NULL, empresa TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS tickets (id INTEGER PRIMARY KEY, cliente_id INTEGER NOT NULL REFERENCES clientes(id) ON DELETE RESTRICT, agente_id INTEGER REFERENCES agentes(id) ON DELETE SET NULL, titulo TEXT NOT NULL, descripcion TEXT NOT NULL, area TEXT NOT NULL CHECK(area IN ('hardware','software','redes')), prioridad TEXT NOT NULL CHECK(prioridad IN ('alta','media','baja')), estado TEXT NOT NULL DEFAULT 'abierto' CHECK(estado IN ('abierto','en progreso','resuelto','cerrado')), fecha_creacion TEXT NOT NULL, fecha_limite TEXT NOT NULL, fecha_resolucion TEXT);
CREATE TABLE IF NOT EXISTS comentarios (id INTEGER PRIMARY KEY, ticket_id INTEGER NOT NULL REFERENCES tickets(id) ON DELETE CASCADE, autor TEXT NOT NULL, texto TEXT NOT NULL, tipo TEXT NOT NULL DEFAULT 'general' CHECK(tipo IN ('general','resolucion')), fecha TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS historial (id INTEGER PRIMARY KEY, ticket_id INTEGER NOT NULL REFERENCES tickets(id) ON DELETE CASCADE, campo TEXT NOT NULL, valor_anterior TEXT, valor_nuevo TEXT, fecha TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_tickets_estado ON tickets(estado);
CREATE INDEX IF NOT EXISTS idx_tickets_agente ON tickets(agente_id);
CREATE INDEX IF NOT EXISTS idx_tickets_area ON tickets(area);
